    local function rem(a, b)
        local r = a % b
        if r ~= 0 and (r ~ a) < 0 then r = r - b end
        return r
    end
    local function div(a, b)
        local q = a // b
        if a % b ~= 0 and (a ~ b) < 0 then q = q + 1 end
        return q
    end
    return div, rem
]], "=wd_division")()
    wd_div = function(a, b)
        if b == 0 then wd_fail("division by zero") end
        return div(a, b)
    end
    wd_mod = function(a, b)
        if b == 0 then wd_fail("division by zero") end
        return rem(a, b)
    end
end

