        local subject = v.kind
        local start = offset
        local tree = tree:add(wd.f_body, tvb(offset, tvb:len() - offset))
        local name = wd_case_name(wd.names_body, subject)
        tree:append_text(": " .. name)
        wd_info_cases["body"] = name
