            offset = offset + 2
        elseif subject == 1 then
            offset = wd.dissect_Pair(tvb, pinfo, tree, offset, wd.site_trailer__Pair)
            if not offset then
                return nil
            end
        else
            wd_unmatched(tree, wd_f_unmatched, wd_ei_unmatched, tvb, offset, subject, "trailer")
            return nil
        end
        tree:set_len(offset - start)
    end
